def apply(page):
    missing = []
    for a, b in PROOF:
        cands = [a, a.replace('&amp;', '&'), a.replace("'", '’'), a.replace('’', "'")]
        hit = next((c for c in cands if c in page), None)
        if hit is None:
            missing.append(a[:60]); continue
        page = page.replace(hit, b)
    import re as _re
    page=_re.sub(r'\bChapter (\d+)\b',r'Lesson \1',page)
    page=_re.sub(r'\bchapter (\d+)\b',r'lesson \1',page)
    page=_re.sub(r'\bModule (\d+)\b',r'Lesson \1',page)
    page=page.replace('Every chapter ends','Every lesson ends').replace('end of this chapter','end of this lesson').replace('through the chapters','through the lessons')
    for a,b in [('we offer long-term stays of 31+ nights', 'we offer mid-term stays of 31+ nights'), ('While long-term stays tend to generate less income per night', 'While monthly stays tend to generate less income per night'), ('Are short- or long-term rentals legally allowed in this area?', 'Are short- or mid-term rentals legally allowed in this area?'), ('While we do accommodate long-term stays and multiple room bookings', 'While we do accommodate mid-term stays and multiple room bookings'), ('Long-term guests often stick pictures', 'Mid-term guests often stick pictures'), ('Recommended if you offer long-term stays', 'Recommended if you offer mid-term stays'), ('furnished mid-stay rental', 'furnished mid-term rental'), ('short-to-mid term stays', 'short- and mid-term stays')]:
        if a not in page: missing.append(a)
        page=page.replace(a,b)
    a='<strong>What made the difference is that they took action anyway.</strong></p>'
    if a in page:
        page=page.replace(a,a+'\n<p>Many people also feel resistance to <strong>pitching landlords</strong>, afraid they’ll say no. But many owners want exactly what you offer: rent paid on time and a well-kept property. <strong>You only need one yes,</strong> and Lesson 6 gives you the scripts.</p>',1)
    else: missing.append('pitch-fear')
    for a,b in [('Most people assume landlords will say no to short-term rentals.','Most people assume landlords will say no to subletting.'),('With short-term rentals, you offer a smart alternative:','With rental arbitrage, you offer a smart alternative:'),('And every stay comes with Airbnb’s host protection and insurance on top.','And on top of that, you take out rental insurance.')]:
        if a not in page: missing.append(a)
        page=page.replace(a,b)
    page=_re.sub(r'<p>\s*→\s*</p>\s*','',page)
    page=_re.sub(r'<li[^>]*>If you need to share extra info, use a document or link\.</li>','',page)
    a='<li><strong>Always keep a spare set of keys or a backup access solution.</strong>'
    if a in page:
        page=page.replace(a,'<li><strong>Label the right washing machine program.</strong> Put a clear sticker or a big red arrow on the program guests should use. Otherwise they’ll pick the longest 3-hour cycle, which costs you more and takes up the machine.</li><li><strong>Don’t take things personally.</strong> Most guests are amazing, but once in a while you’ll get one who is simply unfair. Stay calm, stay professional and focus on the facts. It’s not about you.</li>'+a,1)
    else: missing.append('mistakes-add')
    page=page.replace('Your step-by-step guide to building a property rental business','Your step-by-step course for building a property rental business')
    page=_re.sub(r'\b(this|This|the|The|our|Our) guide\b',r'\1 course',page)
    page=page.replace('Host Guide','Host Course').replace('6-Figure Host Guide','6-Figure Host Course')
    return page, missing
